import {
  generateTerrain,
  sampleHeight,
  type TerrainData,
} from "@/lib/garden/terrain";

/**
 * Garden configuration. The terrain is a rectangular heightfield slab
 * (per wireframe) generated by the ported terrain generator; the strip
 * camera stands on it at eye level looking toward the flower band.
 */
export const GARDEN = {
  terrain: {
    // 64×44 grid at 0.7 world units/cell → ~44 × 30 world units
    gridWidth: 64,
    gridHeight: 44,
    scale: 0.7,
    heightScale: 2.4, // gentle hills — a garden, not the alps
    octaves: 5,
    frequency: 1.5,
  },
  grass: {
    count: 24000,
    tuftWidth: 0.55, // Grass.png is a multi-blade tuft, roughly square
    tuftHeight: 0.55,
    slopeThreshold: 0.55,
    seed: 1,
  },
  flower: {
    width: 0.6, // web-terrain Foliage defaults
    height: 0.8,
    band: { zMin: 1.0, zMax: 5.0 }, // world z, in front of the strip camera
    maxHalfSpread: 13,
  },
  camera: {
    stripZ: 9.5, // strip camera stands here on the terrain
    eyeHeight: 1.9,
    targetZ: -1.5,
    targetHeight: 1.0,
    fov: 45,
  },
  wind: { speed: 1.2, strength: 0.25 }, // web-terrain Scene defaults
} as const;

let cachedTerrain: TerrainData | null = null;

/** The garden's single terrain instance — deterministic, so cache it. */
export function getGardenTerrain(): TerrainData {
  if (!cachedTerrain) {
    const t = GARDEN.terrain;
    cachedTerrain = generateTerrain(
      t.gridWidth,
      t.gridHeight,
      t.scale,
      t.heightScale,
      t.octaves,
      t.frequency,
    );
  }
  return cachedTerrain;
}

/** Serializable subset of PostMetadata that crosses the server → client boundary. */
export interface GardenPost {
  slug: string;
  title: string;
  description: string;
  tags: string[];
  createdAt: string;
  status: string;
}

/** FNV-1a → [0, 1). Deterministic across builds/sessions. */
export function hashSlug(slug: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < slug.length; i++) {
    h ^= slug.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0) / 4294967296;
}

export interface FlowerPlacement {
  slug: string;
  x: number;
  y: number; // terrain height at (x, z)
  z: number;
  /** deterministic per-post random: sway phase + rotation variation */
  rand: number;
  /** flower_1.png vs flower_2.png, decided by the slug */
  textureIndex: 0 | 1;
}

/**
 * One flower per post, spread across the strip's width.
 * Deterministic: each post gets an even slot (posts arrive sorted by
 * createdAt from getPublishedPosts), then its slug hash jitters it inside
 * the slot and picks its depth in the flower band — a slug always blooms
 * in the same place, rooted on the real terrain via sampleHeight.
 */
export function layoutFlowers(
  posts: GardenPost[],
  terrain: TerrainData = getGardenTerrain(),
): FlowerPlacement[] {
  const n = posts.length;
  if (n === 0) return [];

  const halfSpread = Math.min(
    GARDEN.flower.maxHalfSpread,
    Math.max(3.5, n * 1.15),
  );
  const slotWidth = (halfSpread * 2) / n;
  const { zMin, zMax } = GARDEN.flower.band;

  return posts.map((post, i) => {
    const hx = hashSlug(post.slug + ":x");
    const hz = hashSlug(post.slug + ":z");
    const rand = hashSlug(post.slug + ":r");

    const slotCenter = -halfSpread + slotWidth * (i + 0.5);
    const x = slotCenter + (hx - 0.5) * slotWidth * 0.8;
    const z = zMin + hz * (zMax - zMin);

    const sampled = sampleHeight(terrain, x, z);
    const y = sampled <= -999 ? 0 : sampled;

    return {
      slug: post.slug,
      x,
      y,
      z,
      rand,
      textureIndex: rand < 0.5 ? 0 : 1,
    };
  });
}
